/* 按NPC关系和场景挑一条合适的主动消息 */
function pickProactive(p,scene){
 var pool=[];
 if(p.isLover)pool=pool.concat(NPC_PROACTIVE.lover);
 if((p.aff||0)>=60)pool=pool.concat(NPC_PROACTIVE.crush, NPC_PROACTIVE.friend);
 if(scene==='class')pool=pool.concat(NPC_PROACTIVE.class);
 pool=pool.concat(NPC_PROACTIVE.common);
 if((p.aff||0)>=35)pool=pool.concat(NPC_PROACTIVE.friend);
 return pk(pool);
}

/* ---------- ③ 情绪强度判定 ---------- */
function patchEmotion(s){
 s=String(s);
 var info={laugh:0,anger:0,sad:0,surprise:0,question:0,strength:1,raw:s};
 var lh=(s.match(/哈/g)||[]).length; info.laugh=lh;
 if(lh>=4)info.strength=Math.max(info.strength,2.5);
 else if(lh>=2)info.strength=Math.max(info.strength,1.6);
 info.anger=(s.match(/[气怒操艹滚]|！{2,}/g)||[]).length;
 if(/气死|烦死|恶心|讨厌|垃圾/.test(s))info.anger+=2;
 info.sad=(/难过|想哭|委屈|失落|伤心|心情不好|emo/.test(s))?1:0;
 info.surprise=(s.match(/[哇啊喔]|！/g)||[]).length;
 info.question=(s.match(/？|\?|吗|呢|怎么|什么|为什么/g)||[]).length;
 var excl=(s.match(/！|!/g)||[]).length;
 if(excl>=2)info.strength=Math.max(info.strength,2);
 // 重复字（激动/结巴）
 if(/(.)\1{2,}/.test(s))info.strength=Math.max(info.strength,1.8);
 info.primary = info.anger>=2?'anger': info.sad?'sad': info.laugh>=2?'laugh': info.question?'question': info.surprise?'surprise':'normal';
 return info;
}

/* ---------- ④ 归一化（谐音/缩写/错别字） ---------- */
function patchNormalize(s){
 s=String(s).toLowerCase().replace(/[\s，。！？、,.!?~～…"'“”·：:;；（）()]/g,'');
 // 先替换多字俚语（长的优先）
 var keys=[];for(var k in PATCH_SLANG){keys.push(k);}
 keys.sort(function(a,b){return b.length-a.length;});
 for(var i=0;i<keys.length;i++){
   var k=keys[i].toLowerCase();
   var guard=0; while(s.indexOf(k)>=0&&guard<6){ s=s.split(k).join(PATCH_SLANG[keys[i]]); guard++; }
 }
 return s;
}

/* ---------- ⑤ 增强匹配 ---------- */
function patchMatch(input,ctx){
 if(!input)return null;
 var raw=String(input);
 var s=patchNormalize(raw);
 if(!s)return null;
 var best=null,bestSc=0;
 function setBest(kind,ref,sc,kw){ if(sc>bestSc){bestSc=sc;best={kind:kind,ref:ref,sc:sc,intent:kind==='intent'?ref:null,kw:kw||null};} }
 // ① 话题意图（四批全部）
 for(var i=0;i<ALL_TOPIC_INTENTS.length;i++){
  var it=ALL_TOPIC_INTENTS[i];
  if(ctx&&ctx.role&&it.role&&it.role.indexOf(ctx.role)<0)continue;
  for(var j=0;j<it.kws.length;j++){
   var kw=patchNormalize(it.kws[j]);
   if(!kw)continue;
   if(s===kw){setBest('intent',it,1);}
   else if(kw.length>=2&&s.indexOf(kw)>=0){
    var sc=(kw.length/s.length)*1.1;
    if(ctx&&ctx.arch&&it.boost&&it.boost[ctx.arch])sc+=0.15;
    setBest('intent',it,sc);
   }
  }
 }
 // ② 事实类问题
 for(var a=0;a<FACT_QA.length;a++){
  var fq=FACT_QA[a];
  for(var b=0;b<fq.kws.length;b++){
   var fkw=patchNormalize(fq.kws[b]);
   if(!fkw)continue;
   if(s===fkw)setBest('fact',fq,0.99);
   else if(fkw.length>=2&&s.indexOf(fkw)>=0)setBest('fact',fq,(fkw.length/s.length)*0.8);
  }
 }
 // ③ 应答短语（单字只在完全相等时命中，≥2字才做包含匹配，且权重低）
 for(var c=0;c<ACK_LIB.length;c++){
  var ak=ACK_LIB[c];
  for(var d=0;d<ak.kws.length;d++){
   var akw=patchNormalize(ak.kws[d]);
   if(!akw)continue;
   if(s===akw)setBest('ack',ak,1.02,akw);
   else if(akw.length>=2&&s.indexOf(akw)>=0)setBest('ack',ak,(akw.length/s.length)*0.8,akw);
  }
 }
 return best;
}

/* 统一回复：根据匹配结果（话题/事实/应答）生成文本 */
function patchAnswer(m,p,ctx,input){
 if(!m)return null;
 if(m.kind==='fact'){ try{return m.ref.f(p);}catch(e){return null;} }
 if(m.kind==='ack'){
  var band=(p.aff||0)>=70?2:(p.aff||0)>=35?1:0;
  var arr=m.ref[['cold','mid','warm'][band]];
  var key=String(input||'').replace(/\s/g,'');
  // 词根集合：命中的关键词 + 去语气尾字 + 类专属词根
  var roots=[];
  if(m.kw)roots.push(m.kw, m.kw.replace(/[吗呢啊吧呀哦哈的了么]+$/,''));
  var extra={ack_laugh:['笑'],ack_praise:['厉害','一般','还好'],ack_surprise:['真的','少见']};
  if(extra[m.ref.type])roots=roots.concat(extra[m.ref.type]);
  if(m.ref.type==='ack_greet'&&m.kw)roots.push(m.kw.charAt(0));
  function hit(r){ for(var a=0;a<roots.length;a++){var rt=roots[a]; if(rt&&rt.length>=1&&r.indexOf(rt)>=0)return true;}
    for(var i=0;i<key.length-1;i++){var g=key.substr(i,2); if(g&&r.indexOf(g)>=0)return true;} return false; }
  var cand=arr.filter(hit);
  return pk(cand.length?cand:arr);
 }
 return patchReply(m.ref,p,ctx,input);
}

/* ---------- ⑥ 关系阶段 ---------- */
function patchStage(p){
 var aff=p.aff||0;
 if(p.isEx)return 'ex';
 if(p.isLover)return aff>=85?'lover_deep':'lover';
 if(aff>=70)return 'ambient';
 if(aff>=35)return 'friend';
 return 'stranger';
}

/* ---------- ⑦ 隐私/雷区判定 ---------- */
var PATCH_PRIVATE=['你多重','体重多少','三围','有没有钱','存款','家里有钱','爸妈工资','一个月多少生活费','内衣','内裤','第一次','还是处','性经历','家庭住址','手机号多少','身份证'];
function patchPrivacy(input,p){
 var s=String(input);
 for(var i=0;i<PATCH_PRIVATE.length;i++){
  if(s.indexOf(PATCH_PRIVATE[i])>=0){
   var stage=patchStage(p);
   if(stage==='stranger'||stage==='friend')return true; // 关系不够，回避
  }
 }
 return false;
}
/* 踩雷话题（按身份） */
function patchLandmine(input,p){
 var s=String(input);
 if(p.arch==='study'&&/学习没用|读书无用|成绩好有什么用/.test(s))return -6;
 if(p.arch==='sport'&&/四肢发达|体育生成绩差|打球没用/.test(s))return -6;
 if(p.onDiet&&/你胖|又胖了|该减肥|双下巴|小肚腩/.test(s))return -8;
 if(p.isLover&&/前任|你前对象|谁谁好看|别人对象/.test(s))return -4;
 return 0;
}

/* ---------- ⑧ 增强回复 ---------- */
function patchReply(it,p,ctx,input){
 var aff=p.aff||0;
 // 隐私回避
 if(patchPrivacy(input,p)){
  return pk(['嗯？你问这个干嘛','……我们还没熟到聊这个吧','哈哈，这是秘密','你猜呀～不告诉你']);
 }
 var band=aff>=70?'warm':aff>=35?'mid':'cold';
 var arr=(it.rep[band]||it.rep.mid);
 var r=pk(arr);
 var stage=patchStage(p);
 var emo=patchEmotion(input);
 // 身份口吻前缀/后缀
 if(p.arch==='study'&&band==='cold'&&ch(.4))r='这个嘛…'+r;
 if(p.arch==='sport'&&ch(.4))r+='哈';
 if(ctx&&ctx.scene==='class'&&ch(.6))r='（小声）'+r+'，下课再说';
 if(ctx&&ctx.scene==='dorm'&&band==='warm'&&ch(.5))r+='，不早了，别熬太晚';
 // 情绪回应
 if(emo.primary==='anger'&&band!=='cold')r='怎么啦谁惹你了？'+r;
 if(emo.primary==='sad'&&band==='warm')r='抱抱～'+r;
 if(emo.primary==='laugh')r=r;
 // 性格
 if(p.per==='傲娇'&&band==='warm'&&ch(.5))r='才、才不是特意…'+r;
 if(p.per==='高冷'&&ch(.5))r=r.replace(/～/g,'');
 if(p.per==='话痨'&&ch(.4))r+='对了还有啊…';
 return r;
}


