// ========== PATCH命名空间（零冲突设计）==========
const PATCH = {
  version: '7.0',
  config: {
    disableModules: [],
    saveKey: 'patch_v4_save',
    particleCount: 30
  },
  state: {
    money: 1000,
    day: 1,
    season: 0, // 0春1夏2秋3冬
    weather: '晴天',
    mbti: null,
    mbtiEnabled: true,
    roguelike: { active: false, seed: null, day: 0, fragments: 0 },
    social: { npcs: {}, gossip: [] },
    economy: { money: 1000, income: 0, inflation: 0 },
    skills: {},
    streaming: { active: false, fans: 0, viewers: 0 },
    mods: [],
    karaoke: { songs: [], customSongs: [] }
  },
  
  // 工具函数
  utils: {
    rnd: (a, b) => Math.floor(Math.random() * (b - a + 1)) + a,
    ch: (p) => Math.random() < p,
    pk: (a) => String.fromCharCode(65 + Math.floor(Math.random() * a)),
    formatNum: (n) => n >= 10000 ? (n/10000).toFixed(1) + '万' : n.toString(),
    clamp: (v, min, max) => Math.max(min, Math.min(max, v)),
    debounce: (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; },
    save: () => localStorage.setItem(PATCH.config.saveKey, JSON.stringify(PATCH.state)),
    load: () => {
      const d = localStorage.getItem(PATCH.config.saveKey);
      if (d) Object.assign(PATCH.state, JSON.parse(d));
    }
  },

  // 粒子系统
  particles: {
    init: () => {
      const container = document.getElementById('patch-particles');
      if (!container) return;
      for (let i = 0; i < PATCH.config.particleCount; i++) {
        const p = document.createElement('div');
        p.className = 'particle';
        p.style.left = Math.random() * 100 + '%';
        p.style.animationDuration = (Math.random() * 10 + 10) + 's';
        p.style.animationDelay = Math.random() * 10 + 's';
        p.style.width = p.style.height = (Math.random() * 4 + 2) + 'px';
        const colors = ['#4a7dff', '#ff6b9d', '#00d9a6', '#ffa726'];
        p.style.background = colors[Math.floor(Math.random() * colors.length)];
        container.appendChild(p);
      }
    }
  },

  // 评分飘字特效
  scorePop: (text, x, y, color = '#4a7dff') => {
    const el = document.createElement('div');
    el.className = 'score-pop';
    el.textContent = text;
    el.style.left = x + 'px';
    el.style.top = y + 'px';
    el.style.color = color;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 1000);
  },

  // 提示消息
  toast: (msg, type = 'info') => {
    const el = document.createElement('div');
    el.style.cssText = `
      position:fixed;top:20px;right:20px;padding:12px 24px;
      border-radius:8px;color:white;font-size:14px;z-index:99999;
      animation:fadeIn 0.3s ease;
      background:${type === 'success' ? 'var(--success)' : type === 'danger' ? 'var(--danger)' : 'var(--accent)'};
      box-shadow:0 4px 15px rgba(0,0,0,0.3);
    `;
    el.textContent = msg;
    document.body.appendChild(el);
    setTimeout(() => {
      el.style.opacity = '0';
      el.style.transition = 'opacity 0.3s';
      setTimeout(() => el.remove(), 300);
    }, 3000);
  },

  // 面板切换
  openPanel: (panelId) => {
    document.getElementById('patch-main-panel').classList.add('active');
    document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
    const panel = document.getElementById('panel-' + panelId);
    const nav = document.querySelector(`.nav-item[data-panel="${panelId}"]`);
    if (panel) panel.classList.add('active');
    if (nav) nav.classList.add('active');
    // 初始化各系统
    if (panelId === 'social') PATCH.social.init();
    if (panelId === 'economy') PATCH.economy.init();
    if (panelId === 'skills') PATCH.skills.init();
    if (panelId === 'weather') PATCH.weather.init();
    if (panelId === 'streaming') PATCH.streaming.init();
    if (panelId === 'modshop') PATCH.modshop.init();
    if (panelId === 'karaoke') PATCH.karaoke.init();
    if (panelId === 'tests') PATCH.tests.init();
    if (panelId === 'mbti') PATCH.mbti.init();
    if (panelId === 'ancient') PATCH.ancientWisdom.init();
    if (panelId === 'ancient') PATCH.ancientWisdom.init();
  },
  closePanel: () => {
    document.getElementById('patch-main-panel').classList.remove('active');
    PATCH.streaming.stopStream();
  },

  // 初始化
  init: () => {
    PATCH.utils.load();
    PATCH.particles.init();
    
    // 控制台按钮事件
    document.getElementById('patch-console-btn').addEventListener('click', () => {
      PATCH.openPanel('dashboard');
    });
    
    // 导航事件
    document.querySelectorAll('.nav-item').forEach(item => {
      item.addEventListener('click', () => {
        const panel = item.dataset.panel;
        PATCH.openPanel(panel);
      });
    });
    
    // 键盘快捷键 ESC关闭
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') PATCH.closePanel();
    });
    
    PATCH.toast('PATCH v7.0 已加载', 'success');
  }
};

// ========== 学期Roguelike系统 ==========
PATCH.roguelike = {
  start: () => {
    const seed = PATCH.utils.pk(6).toUpperCase();
    PATCH.state.roguelike = { active: true, seed: seed, day: 1, fragments: 0 };
    document.getElementById('rl-seed').textContent = seed;
    document.getElementById('rl-day').textContent = '1';
    document.getElementById('rl-fragments').textContent = '0';
    document.getElementById('rl-progress').style.width = '0%';
    PATCH.toast('新学期开始！种子码: ' + seed, 'success');
    // 模拟游戏循环
    PATCH.roguelike.loop();
  },
  loop: () => {
    if (!PATCH.state.roguelike.active) return;
    PATCH.state.roguelike.day++;
    document.getElementById('rl-day').textContent = PATCH.state.roguelike.day;
    // 随机事件
    if (PATCH.utils.ch(0.3)) {
      const events = [
        '你在图书馆发现了一张记忆碎片！',
        '食堂阿姨多给了你一份鸡腿！',
        '老师在课堂上表扬了你！',
        '你在操场捡到了一块钱！',
        '同学邀请你一起吃饭！'
      ];
      PATCH.toast(events[Math.floor(Math.random() * events.length)], 'info');
      if (PATCH.utils.ch(0.2)) {
        PATCH.state.roguelike.fragments++;
        document.getElementById('rl-fragments').textContent = PATCH.state.roguelike.fragments;
        PATCH.toast('获得记忆碎片！(' + PATCH.state.roguelike.fragments + '/20)', 'success');
      }
    }
    // 进度条
    const progress = (PATCH.state.roguelike.day % 30) / 30 * 100;
    document.getElementById('rl-progress').style.width = progress + '%';
    setTimeout(() => PATCH.roguelike.loop(), 5000);
  },
  season: () => {
    PATCH.toast('赛季通行证系统开发中...', 'info');
  },
  unlockPerk: (idx) => {
    PATCH.toast('永久加成解锁功能开发中...', 'info');
  }
};

// ========== 深度社交关系网 ==========
PATCH.social = {
  npcs: [
    { id: 1, name: '班长小明', avatar: '👦', favor: 50, maxFavor: 100, trait: '热心肠', relation: '同学' },
    { id: 2, name: '学霸小红', avatar: '👧', favor: 40, maxFavor: 100, trait: '高冷', relation: '同桌' },
    { id: 3, name: '体育委员小刚', avatar: '🧑', favor: 60, maxFavor: 100, trait: '阳光', relation: '朋友' },
    { id: 4, name: '文艺委员小丽', avatar: '👩', favor: 35, maxFavor: 100, trait: '温柔', relation: '邻居' },
    { id: 5, name: '同桌小伟', avatar: '👦', favor: 45, maxFavor: 100, trait: '幽默', relation: '同桌' },
    { id: 6, name: '学姐小雅', avatar: '👩‍🎓', favor: 30, maxFavor: 100, trait: '成熟', relation: '学姐' },
    { id: 7, name: '校草阿杰', avatar: '🧑‍🦱', favor: 55, maxFavor: 100, trait: '自信', relation: '校友' },
    { id: 8, name: '学妹小柔', avatar: '👧', favor: 25, maxFavor: 100, trait: '可爱', relation: '学妹' }
  ],
  gossipList: [
    '听说班长晚上在图书馆加班到很晚...',
    '学霸小红好像有喜欢的人？',
    '体育委员小刚昨天篮球赛投了个三分球！',
    '文艺委员小丽会弹钢琴！',
    '同桌小伟其实是游戏高手！',
    '学姐小雅之前是模特！',
    '校草阿杰会写歌！',
    '学妹小柔是学霸转来的！'
  ],
  init: () => {
    const container = document.getElementById('social-npcs');
    container.innerHTML = '';
    PATCH.social.npcs.forEach(npc => {
      const div = document.createElement('div');
      div.style.cssText = 'padding:12px;border-bottom:1px solid var(--border-glass);';
      div.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
          <span style="font-size:24px;">${npc.avatar}</span>
          <div style="flex:1;">
            <div style="display:flex;justify-content:space-between;">
              <strong>${npc.name}</strong>
              <span style="color:var(--text-secondary);font-size:12px;">${npc.relation}</span>
            </div>
            <div style="font-size:12px;color:var(--text-secondary);">特质: ${npc.trait}</div>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:10px;">
          <span style="font-size:12px;">好感度 ${npc.favor}/${npc.maxFavor}</span>
          <div class="progress-bar" style="flex:1;">
            <div class="progress-fill" style="width:${npc.favor}%;background:var(--accent2);"></div>
          </div>
        </div>
        <div style="margin-top:8px;display:flex;gap:6px;">
          <button class="btn btn-sm btn-primary" onclick="PATCH.social.interact(${npc.id}, 'talk')">聊天</button>
          <button class="btn btn-sm btn-success" onclick="PATCH.social.interact(${npc.id}, 'gift')">送礼</button>
          <button class="btn btn-sm btn-warning" onclick="PATCH.social.interact(${npc.id}, 'help')">帮忙</button>
        </div>
      `;
      container.appendChild(div);
    });
    // 八卦
    const gossipContainer = document.getElementById('social-gossip');
    gossipContainer.innerHTML = '';
    PATCH.social.gossipList.forEach((g, i) => {
      const div = document.createElement('div');
      div.style.cssText = 'padding:8px 0;border-bottom:1px solid var(--border-glass);font-size:13px;color:var(--text-secondary);';
      div.textContent = '💬 ' + g;
      gossipContainer.appendChild(div);
    });
  },
  interact: (id, type) => {
    const npc = PATCH.social.npcs.find(n => n.id === id);
    if (!npc) return;
    let change = 0;
    switch(type) {
      case 'talk': change = PATCH.utils.rnd(3, 8); break;
      case 'gift': change = PATCH.utils.rnd(8, 15); break;
      case 'help': change = PATCH.utils.rnd(5, 12); break;
    }
    npc.favor = PATCH.utils.clamp(npc.favor + change, 0, npc.maxFavor);
    PATCH.toast(`${npc.name} 好感度 +${change} (当前${npc.favor})`, 'success');
    PATCH.social.init(); // 刷新显示
  },
  generateGossip: () => {
    const newGossip = '【新八卦】' + ['听说学校要换校长了...', '据说食堂要涨价了...', '有人看到校长和小丽在聊天...', '传说学校地下有秘密通道...', '隔壁班在传小红和小明的八卦...'][PATCH.utils.rnd(0, 4)];
    PATCH.social.gossipList.unshift(newGossip);
    if (PATCH.social.gossipList.length > 10) PATCH.social.gossipList.pop();
    PATCH.social.init();
    PATCH.toast('获取到新八卦！', 'info');
  }
};

// ========== 校园经济系统 ==========
PATCH.economy = {
  init: () => {
    document.getElementById('eco-money').textContent = PATCH.state.economy.money;
    document.getElementById('eco-income').textContent = PATCH.state.economy.income;
    document.getElementById('eco-inflation').textContent = PATCH.state.economy.inflation + '%';
  },
  work: (type) => {
    let amount = 0;
    let msg = '';
    switch(type) {
      case 'parttime':
        amount = 50;
        msg = '兼职打工赚了50元';
        break;
      case 'invest':
        if (PATCH.state.economy.money >= 100) {
          const success = PATCH.utils.ch(0.6);
          amount = success ? PATCH.utils.rnd(30, 150) : -PATCH.utils.rnd(20, 80);
          msg = success ? `投资成功！赚了${amount}元` : `投资失败！亏了${Math.abs(amount)}元`;
        } else {
          msg = '投资需要至少100元启动资金';
          PATCH.toast(msg, 'danger');
          return;
        }
        break;
      case 'black':
        if (PATCH.utils.ch(0.4)) {
          amount = PATCH.utils.rnd(100, 300);
          msg = `黑市交易成功！赚了${amount}元（风险：可能被抓住）`;
        } else {
          amount = -PATCH.utils.rnd(50, 150);
          msg = `黑市交易被抓！亏了${Math.abs(amount)}元`;
        }
        break;
    }
    PATCH.state.economy.money += amount;
    PATCH.state.economy.money = Math.max(0, PATCH.state.economy.money);
    document.getElementById('eco-money').textContent = PATCH.state.economy.money;
    PATCH.toast(msg, amount >= 0 ? 'success' : 'danger');
  }
};

